#!/bin/sh
# Melon Dice managed launcher v1. Generated by scripts/install.py.
melondice_python=@PYTHON@
melondice_root=@ROOT@
if [ ! -x "$melondice_python" ]; then
    printf '%s\n' "Melon Dice: installation Python is missing: $melondice_python" \
        'Run python3 scripts/install.py from the project source to repair the installation.' >&2
    exit 1
fi
if [ ! -f "$melondice_root/bootstrap.py" ]; then
    printf '%s\n' "Melon Dice: installation bootstrap is missing: $melondice_root/bootstrap.py" \
        'Run python3 scripts/install.py from the project source to repair the installation.' >&2
    exit 1
fi
exec "$melondice_python" -I "$melondice_root/bootstrap.py" "$@"
